from taf.internal.gnb.oam.rap.client.rap.v2 import SMApi, ApiClient, Configuration
from taf.internal.gnb.oam.rap.client.rap.v2 import InitializeOperationRequestBody
from taf.internal.gnb.oam.rap.client.rap.v2.exceptions import ApiException
from taf.sbts.oam.sc.rest.exception import AsirOperationTimeout
from urllib3.util.retry import MaxRetryError
import logging
import time

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class SmV1(object):

    def __init__(self, con_details, access_token):
        self.configuration = self._create_configuration_prepare(con_details)
        self.configuration.access_token = access_token
        self.sm_api_instance = SMApi(ApiClient(self.configuration))

    @staticmethod
    def _create_configuration_prepare(con_details):
        config_object = Configuration()
        config_object.host = con_details.make_configuration_host(original_endpoint=config_object.host)
        config_object.retries = 0
        config_object.verify_ssl = con_details.secure
        return config_object

    def get_site_info(self):
        return self.sm_api_instance.sm_site_get()

    def reset_configuration(self):
        initialize_operation_request_body = InitializeOperationRequestBody("configurationReset", False)
        return self.sm_api_instance.sm_site_post(initialize_operation_request_body=initialize_operation_request_body)

    def get_unit_available_operations(self, uid):
        return self.sm_api_instance.sm_units_uid_capabilities_get(uid=uid)

    def perform_operation_on_unit(self, uid, operation, timeout):
        initialize_operation_request_body = InitializeOperationRequestBody(operation, False, self.configuration)
        operation_response = self.sm_api_instance.sm_units_uid_jobs_post(
            uid, initialize_operation_request_body=initialize_operation_request_body)
        if timeout == 0:
            return operation_response
        else:
            return self._wait_for_operation_to_finish(uid=uid, job_id=operation_response.job_id, operation=operation,
                                                      timeout=timeout)

    def _wait_for_operation_to_finish(self, uid, job_id, operation, timeout):  # noqa: C901
        start_time = time.time()
        logging.info("Operation '{}' on unit {} in progress ...".format(operation, uid))
        while time.time() - start_time < timeout:
            try:
                job_completed_response = self.sm_api_instance.sm_units_uid_jobs_job_id_get(uid, job_id)
                if job_completed_response.location:
                    return self.sm_api_instance.sm_units_uid_jobs_job_id_result_get(uid, job_id)
                else:
                    continue
            except MaxRetryError:
                logging.info("Cannot connect to ASIR Webem - waiting 1 sec for next attempt")
                time.sleep(1)
                continue
            except ApiException as e:
                if "503 Service Unavailable" in str(e):
                    logging.info("ASIR WebEM is Unavailable - waiting 10 sec for next attempt")
                    time.sleep(10)
                    continue
                else:
                    raise e
        else:
            raise AsirOperationTimeout(
                "Cannot finish operation '{}' on unit '{}' in {} seconds (job_id={})".format(operation, uid, timeout,
                                                                                             job_id))
